def create_demo():
    rows = []
    for category, block in EXAMPLES.items():
        for line in block.strip().splitlines():
            question, answer = line.split("|", 1)
            rows.append({"messages": [{"role": "system", "content": SYSTEM},
                                     {"role": "user", "content": question},
                                     {"role": "assistant", "content": answer}],
                         "category": category, "synthetic": True,
                         "source": "orthodox-qwen-original-demo-v1", "license": "CC0-1.0",
                         "document_id": digest(category + question)})
    assert len(rows) == 120
    write_jsonl("data/sft_sources/demo.jsonl", rows)
    return rows


