def create_eval():
    write_jsonl("data/eval/prompts.jsonl", [{"document_id": digest(prompt), "category": category,
                 "messages": [{"role": "system", "content": SYSTEM}, {"role": "user", "content": prompt}],
                 "reference": reference, "source": "orthodox-qwen-heldout-v1", "license": "CC0-1.0",
                 "synthetic": True} for category, prompt, reference in EVAL])
